  "Only you and {name} can see this conversation. They get an email if they're not in the app.": "Solo usted y {name} pueden ver esta conversación. Si no están en la aplicación, reciben un correo.",
  "Everyone on this deal can see this chat. For a private message, switch to 👤 One person above.": "Todos en esta transacción pueden ver este chat. Para un mensaje privado, cambie a 👤 Una persona arriba.",
  "Messages your agent shares with you (and your own) appear here. Your agent also has separate side-conversations with the other agent and vendors — those aren't shown.": "Aquí aparecen los mensajes que su agente comparte con usted (y los suyos). Su agente también tiene conversaciones aparte con el otro agente y los proveedores — esas no se muestran.",
  "Visible to everyone unless you pick a recipient with To: to send a private message. People who aren't in the app get it by email.": "Visible para todos, a menos que elija un destinatario en Para: para enviar un mensaje privado. Quienes no están en la aplicación lo reciben por correo.",
