  "OK": "Aceptar",
  "Plan your utilities & move-out": "Planee sus servicios y su mudanza",
  "As closing nears, arrange for your power, water, and internet to stop or transfer, and have the home cleared out.": "Al acercarse el cierre, organice que la luz, el agua y el internet se suspendan o se transfieran, y deje la casa desocupada.",
  "Gather keys, remotes & garage openers": "Reúna llaves, controles y abridores del garaje",
  "Bring all house keys, garage remotes, mailbox keys, and gate fobs to closing so the new owner can be handed everything.": "Lleve al cierre todas las llaves de la casa, los controles del garaje, las llaves del buzón y los llaveros de acceso para que se le entregue todo al nuevo dueño.",
  "Home warranty": "Garantía de la vivienda",
  "Optional coverage — your agent will tell you if it's part of your deal.": "Cobertura opcional — su agente le dirá si forma parte de su trato.",
  "Final walk-through": "Recorrido final",
