  "Send Invite": "Enviar invitación",
  "Get a portal login link to text or share directly — useful if the invite email didn't arrive. They still set their own PIN.": "Obtenga un enlace de acceso al portal para enviar por texto o compartir directamente — útil si el correo de invitación no llegó. Aun así, ellos definen su propio PIN.",
  "🔗 Login Link": "🔗 Enlace de acceso",
  "Follow Up": "Dar seguimiento",
  "Send (or re-send) the role-specific welcome email with key dates, financial summary, parties roster, and the contract document package. Use this when you've added or corrected this party's email after the initial Under Contract send.": "Enviar (o reenviar) el correo de bienvenida específico según el rol, con fechas clave, resumen financiero, lista de partes y el paquete de documentos del contrato. Úselo cuando haya agregado o corregido el correo de esta parte después del envío inicial de Bajo Contrato.",
  "✉️ Send Welcome": "✉️ Enviar bienvenida",
  "Email a one-time secure link so this party can set a new password. The link expires in 1 hour. Use this when a party calls saying they can't log in.": "Envíe por correo un enlace seguro de un solo uso para que esta parte pueda establecer una nueva contraseña. El enlace expira en 1 hora. Úselo cuando una parte llame diciendo que no puede ingresar.",
  "🔐 Reset PW": "🔐 Restablecer contraseña",
