  "Create the full start-to-finish checklist for this deal — built automatically for its current stage and contract details. Due dates fill in from the contract date when one is set.": "Cree la lista de verificación completa de principio a fin para esta transacción — generada automáticamente según su etapa actual y los detalles del contrato. Las fechas límite se completan a partir de la fecha del contrato cuando esta se establece.",
  "Tip: add a contract date so deadlines and reminders can be calculated. (You can build the list now either way.)": "Consejo: agregue una fecha de contrato para que se puedan calcular los plazos y recordatorios. (De todos modos puede crear la lista ahora.)",
