  "Reject offer": "Rechazar oferta",
  "How offers and counter-offers work here": "Cómo funcionan las ofertas y contraofertas aquí",
  "— the buyer signed the offer; you log it with Receive Offer and the app reads every term.": "— el comprador firmó la oferta; usted la registra con Recibir Oferta y la aplicación lee cada término.",
  "Counter": "Contraoferta",
  "— you change the terms right on the screen, review the email to the buyer's agent and send it. No seller approval or signature yet.": "— usted cambia los términos directamente en la pantalla, revisa el correo para el agente del comprador y lo envía. Aún sin aprobación ni firma del vendedor.",
  "Waiting on the buyer's agent": "Esperando al agente del comprador",
  "— they strike & initial your changes or resubmit. Their reply lands here by itself.": "— ellos tachan e inicialan sus cambios o vuelven a enviar. Su respuesta llega aquí automáticamente.",
  "Check what came back": "Revisar lo que llegó",
  "— compared to the original offer plus only your changes. Anything else that changed is flagged red and must be cleared.": "— comparado con la oferta original más solo sus cambios. Cualquier otra cosa que haya cambiado se marca en rojo y debe resolverse.",
  "Seller signs last": "El vendedor firma al final",
  "— the app places the seller's initials and signature; you check them and send.": "— la aplicación coloca las iniciales y la firma del vendedor; usted las revisa y las envía.",
  "— the listing goes Under Contract with the final terms.": "— el listado pasa a Bajo Contrato con los términos finales.",
  "No pending offers on this listing yet. When a buyer's agent sends one, tap": "Aún no hay ofertas pendientes en este listado. Cuando un agente del comprador envíe una, toque",
  "Receive Offer": "Recibir Oferta",
  "to log it here — then counter, or send it to your seller to sign.": "para registrarla aquí — luego haga una contraoferta, o envíela a su vendedor para que la firme.",
