  "— I'll keep this deal quiet until then. Tap “Check now” to look sooner.": "— mantendré esta transacción en silencio hasta entonces. Toque “Revisar ahora” para revisar antes.",
  "Tap “Run check-up” and I'll review this deal to show the biggest risk right now and the one move to make today.": "Toque “Ejecutar chequeo” y revisaré esta transacción para mostrarle el mayor riesgo en este momento y la acción a tomar hoy.",
