  "Your intake link": "Su enlace de ingreso",
  "Share this with agents or clients so they can submit a deal to you.": "Comparta esto con agentes o clientes para que puedan enviarle una transacción.",
  "No intake requests yet. Share your link to start receiving deals.": "Aún no hay solicitudes de ingreso. Comparta su enlace para empezar a recibir transacciones.",
  "🧭 Assigned to you by the lead coordinator.": "🧭 Asignado a usted por el coordinador(a) principal.",
  "Handled by": "A cargo de",
  "Me (lead coordinator)": "Yo (coordinador(a) principal)",
  "Goes out in the agent's name (or co-branded with you, if enabled).": "Se envía a nombre del agente (o con su marca conjunta, si está habilitado).",
  "Send to": "Enviar a",
  "No party on this deal has an email.": "Ninguna parte de esta transacción tiene correo electrónico.",
  "Subject (for the email)": "Asunto (para el correo)",
