  "Please enter the Year Built (a valid 4-digit year). It's required to determine which disclosures this deal needs — for example, lead-based paint applies only to homes built before 1978.": "Ingrese el año de construcción (un año válido de 4 dígitos). Es necesario para determinar qué divulgaciones requiere esta transacción — por ejemplo, la de pintura con plomo aplica solo a viviendas construidas antes de 1978.",
  "Please answer whether the property is in an HOA or condo association. It determines whether the HOA disclosure is required.": "Indique si la propiedad pertenece a una HOA o asociación de condominio. Esto determina si se requiere la divulgación de HOA.",
