  "✅ When you tap Create, the app builds the deal's timeline, checklist, and reminders for you. Commission details, MLS number, and everything else can be added later from the deal.": "✅ Al presionar Crear, la app arma la cronología, la lista de verificación y los recordatorios de la transacción por usted. Los detalles de comisión, el número de MLS y todo lo demás se pueden agregar después desde la transacción.",
