  "Could not confirm — please try again.": "No se pudo confirmar — intente de nuevo.",
  "✓ Confirm Lead": "✓ Confirmar prospecto",
  "Mark this lead as Not Pursuing? It will be set to Cancelled and removed from your active list (you can reactivate it later). Type CANCEL to confirm.": "¿Marcar este prospecto como No se está gestionando? Se establecerá como Cancelado y se quitará de su lista activa (puede reactivarlo después). Escriba CANCEL para confirmar.",
  "Not pursuing": "No se está gestionando",
  "Could not update — please try again.": "No se pudo actualizar — intente de nuevo.",
  "Send the welcome & intro emails to all parties — you can preview each before it goes out.": "Envíe los correos de bienvenida e introducción a todas las partes — puede previsualizar cada uno antes de enviarlo.",
  "✉️ Preview & Send Welcome Emails": "✉️ Previsualizar y enviar correos de bienvenida",
