  "from intake": "de captación",
  "UNASSIGNED LEAD — Action Required": "PROSPECTO SIN ASIGNAR — Se requiere acción",
  "What to do:": "Qué hacer:",
  "Click the button below to assign this lead to an agent at your brokerage. You can pick yourself if you are taking it.": "Haga clic en el botón de abajo para asignar este prospecto a un agente de su correduría. Puede elegirse a sí mismo si lo va a atender.",
  "Florida law requires prompt first contact (within 24 hours). Until assigned, no one is responsible for this lead and it can go cold quickly. Brokerage admins are notified by email and SMS that this lead is waiting.": "La ley de Florida exige un primer contacto rápido (dentro de 24 horas). Hasta que se asigne, nadie es responsable de este prospecto y puede enfriarse rápidamente. Los administradores de la correduría reciben una notificación por correo electrónico y SMS de que este prospecto está en espera.",
  "What happens after assigning:": "Qué sucede después de asignar:",
  "The assigned agent gets an email + SMS. The card turns red with the \"Contact Within 24hrs\" banner. The 5-step onboarding checklist activates.": "El agente asignado recibe un correo electrónico y un SMS. La tarjeta se pone roja con el aviso \"Contactar dentro de 24 horas\". La lista de verificación de incorporación de 5 pasos se activa.",
  "💵 Cash deal — no lender or financing. No loan application, lender appraisal, or financing contingency applies.": "💵 Transacción en efectivo — sin prestamista ni financiamiento. No aplica solicitud de préstamo, tasación del prestamista ni contingencia de financiamiento.",
