  "The standard non-binding first step on a commercial deal. Generate a ready-to-send draft from this deal's details — every clause is pre-written, just confirm the numbers.": "El primer paso estándar no vinculante en una transacción comercial. Genere un borrador listo para enviar con los datos de esta transacción — cada cláusula está prerredactada, solo confirme las cifras.",
