  "Recommended (optional)": "Recomendado (opcional)",
  "This list adjusts automatically to the deal (HOA, condo, age of home, financing, coastal, foreign seller, etc.). Uploading here labels the file so it's filed correctly. Missing the right trigger? Update the deal's details. To add or reorder your brokerage's required documents, go to": "Esta lista se ajusta automáticamente a la transacción (HOA, condominio, antigüedad de la vivienda, financiamiento, zona costera, vendedor extranjero, etc.). Subir aquí etiqueta el archivo para que se archive correctamente. ¿Falta el disparador correcto? Actualice los datos de la transacción. Para agregar o reordenar los documentos requeridos por su correduría, vaya a",
