  "Seller is not aware of any material defect affecting the value of the Property other than those observable by Buyer or disclosed to Buyer in writing.": "El vendedor no tiene conocimiento de ningún defecto material que afecte el valor de la Propiedad, aparte de los observables por el Comprador o divulgados por escrito al Comprador.",
  "1031 Exchange": "Intercambio 1031",
  "Either party may structure its purchase or sale as part of a tax-deferred exchange under IRC §1031, and the other party shall reasonably cooperate at no additional cost or liability to it.": "Cualquiera de las partes puede estructurar su compra o venta como parte de un intercambio con impuestos diferidos bajo el IRC §1031, y la otra parte deberá cooperar razonablemente sin costo ni responsabilidad adicional para ella.",
