  "Seller does NOT authorize automated value estimates (AVM) next to the listing": "El Vendedor NO autoriza estimaciones automatizadas de valor (AVM) junto al listado",
  "Seller does NOT authorize third-party comments/reviews on the listing": "El Vendedor NO autoriza comentarios/reseñas de terceros en el listado",
