  "eaglecreekhoa.com": "eaglecreekhoa.com",
  "💡 Upload the broker synopsis above and these fill from the sheet. Anything left blank stays": "💡 Suba la sinopsis del corredor arriba y estos se completarán a partir de la ficha. Todo lo que quede en blanco permanecerá",
  "blank on the form": "en blanco en el formulario",
  "for you to complete — never guessed from other contacts.": "para que usted lo complete — nunca se adivina a partir de otros contactos.",
  "Condominium association name": "Nombre de la asociación de condominio",
  "Your interest in the property (Rider AA)": "Su interés en la propiedad (Rider AA)",
  "e.g. Seller is licensee's parent": "ej. El Vendedor es padre/madre del licenciado",
  "Filling the official forms…": "Completando los formularios oficiales…",
  "Generate package →": "Generar paquete →",
  "Review before sending.": "Revisar antes de enviar.",
  "Open each filled form and check every blank — nothing goes to your seller until you hit Send.": "Abra cada formulario completado y revise todos los campos — nada se envía a su vendedor hasta que presione Enviar.",
  "👀 Review PDF": "👀 Revisar PDF",
  "Move, resize, remove, or add signature/initial spots on this document": "Mueva, redimensione, elimine o agregue espacios de firma/inicial en este documento",
  "💰 Include the Seller's Net Sheet": "💰 Incluir la Hoja de Neto del Vendedor",
  "\") in this signing round — your brokerage requires it signed at listing. Seller, co-seller, and your signature lines are placed automatically.": "\") en esta ronda de firmas — su correduría requiere que se firme al momento del listado. Las líneas del vendedor, covendedor y su firma se colocan automáticamente.",
  "No Seller's Net Sheet on this deal yet.": "Aún no hay Hoja de Neto del Vendedor en esta transacción.",
  "Your brokerage requires a SIGNED net sheet at listing — create it under": "Su correduría requiere una hoja de neto FIRMADA al momento del listado — créela en",
  "💰 Money → Seller's Net Sheet": "💰 Dinero → Hoja de Neto del Vendedor",
  ", then reopen this package to include it (or send it separately with ✍️ Get signature).": ", y luego vuelva a abrir este paquete para incluirla (o envíela por separado con ✍️ Obtener firma).",
  "➕ Include more documents in this signing round (optional)": "➕ Incluir más documentos en esta ronda de firmas (opcional)",
  "They ride the same signing session. Signature lines are detected automatically; use ✍️ Get signature separately if a doc needs precise placement.": "Se incluyen en la misma sesión de firma. Las líneas de firma se detectan automáticamente; use ✍️ Obtener firma por separado si un documento necesita una ubicación precisa.",
  "✍️ Signing links go to:": "✍️ Los enlaces de firma van a:",
  ". Every signature and initial line is pre-placed — including the page-bottom initials on every page.": ". Cada línea de firma e inicial está pre-colocada — incluyendo las iniciales al pie de cada página.",
  "✉️ Send for signature": "✉️ Enviar para firma",
  "Listing package sent!": "¡Paquete de listado enviado!",
  "Your seller(s) — and you — each got a private signing link by email. Track progress with the ⏳ badges under Documents. The moment everyone has signed, the signed copies file back here and your listing's launch steps (photos, sign, MLS) unlock automatically.": "Su(s) vendedor(es) — y usted — recibieron un enlace privado de firma por correo electrónico. Siga el progreso con las insignias ⏳ en Documentos. En cuanto todos hayan firmado, las copias firmadas se archivan aquí y los pasos de lanzamiento de su listado (fotos, letrero, MLS) se desbloquean automáticamente.",
  "🧷 Combine PDFs into one file": "🧷 Combinar PDFs en un solo archivo",
  "Check the PDFs in the order you want them merged — the number shows their position. The combined file is saved as a new document; the originals stay put.": "Marque los PDF en el orden en que desea combinarlos — el número indica su posición. El archivo combinado se guarda como un nuevo documento; los originales permanecen intactos.",
  "No PDFs on this deal yet.": "Aún no hay PDFs en esta transacción.",
  "Name for the combined file (e.g. \"MLS attachments package\")": "Nombre para el archivo combinado (ej. \"paquete de anexos de MLS\")",
  "Combining…": "Combinando…",
  "✏️ Adjust signing spots — ": "✏️ Ajustar espacios de firma — ",
  "Drag": "Arrastre",
  "a block to move it · drag the": "un bloque para moverlo · arrastre la",
  "● corner": "● esquina",
  "to resize ·": "para redimensionarlo ·",
  "tap": "toque",
  "a block to remove it · tap the page to add a new one for the selected signer.": "un bloque para eliminarlo · toque la página para agregar uno nuevo para el firmante seleccionado.",
  "💾 Save these spots": "💾 Guardar estos espacios",
  "⚠️ Bounced — email address is wrong": "⚠️ Rebotado — la dirección de correo es incorrecta",
  "📭 Ask them to confirm the welcome email": "📭 Pedirles que confirmen el correo de bienvenida",
  "Review the message. Nothing is sent until you press Send. It includes their one-click ✅ button.": "Revise el mensaje. No se envía nada hasta que presione Enviar. Incluye su botón ✅ de un solo clic.",
  "⚠️ Their last email to": "⚠️ Su último correo a",
  "bounced. Fix the address in People and use their Send Welcome instead — a reminder to the same address will bounce too.": "rebotó. Corrija la dirección en Personas y use su opción Enviar Bienvenida en su lugar — un recordatorio a la misma dirección también rebotará.",
  "✉️ Send reminder": "✉️ Enviar recordatorio",
  "Yes, confirmed": "Sí, confirmado",
  "Could not save — please try again.": "No se pudo guardar — intente de nuevo.",
  "📩 Welcome email received?": "📩 ¿Recibió el correo de bienvenida?",
  "confirmed": "confirmado",
  "✓ They told me they got it": "✓ Me dijeron que lo recibieron",
  "Fix their email on their card below, then use their ✉️ Send Welcome.": "Corrija su correo en su tarjeta abajo, luego use su opción ✉️ Enviar Bienvenida.",
  "💬 New messages —": "💬 Mensajes nuevos —",
  "unread across": "sin leer en",
  "deal": "transacción",
  " · 📥 client reply": " · 📥 respuesta del cliente",
