  "Text message": "Mensaje de texto",
  "Texts are a fixed alert and can't be reworded — uncheck it to hold it.": "Los mensajes de texto son una alerta fija y no se pueden redactar de nuevo — desmárquelo para retenerlo.",
  "As they'll see it": "Como lo verán ellos",
  "✏️ Edit wording": "✏️ Editar texto",
  "↺ Undo my edits": "↺ Deshacer mis cambios",
  "Your edited version will be sent (with": "Se enviará su versión editada (con",
  "your": "su",
  "signature):": "firma):",
  "Email preview": "Vista previa del correo",
  "Your signature is added automatically. Keep the “Mark it done” link so they can confirm in one tap.": "Su firma se agrega automáticamente. Mantenga el enlace “Marcar como hecho” para que puedan confirmar con un toque.",
  "Nothing goes out until you approve.": "No se envía nada hasta que usted lo apruebe.",
  "Reading your contract...": "Leyendo su contrato...",
  "We're identifying every document and pulling out all the key fields. This usually takes 30–60 seconds.": "Estamos identificando cada documento y extrayendo todos los campos clave. Esto suele tardar entre 30 y 60 segundos.",
  "This is taking longer than usual. It may still finish in a moment — or something may have stalled.": "Esto está tardando más de lo habitual. Puede que termine en un momento, o puede que algo se haya detenido.",
  "Go back & try again": "Regresar e intentar de nuevo",
  "Approving THIS offer will replace the accepted offer's price, dates, commission and parties with this one's, and re-run the timeline.\n\n": "Aprobar ESTA oferta reemplazará el precio, las fechas, la comisión y las partes de la oferta aceptada por los de esta, y se volverá a ejecutar la cronología.\n\n",
  "Only do this if you're intentionally switching to this offer. Continue?": "Haga esto solo si está cambiando intencionalmente a esta oferta. ¿Continuar?",
  "Yes, switch offers": "Sí, cambiar de oferta",
  "The seller declined this offer.": "El vendedor rechazó esta oferta.",
  "\n\nApprove it anyway?": "\n\n¿Aprobarla de todas formas?",
  "Approve anyway": "Aprobar de todas formas",
  "✍️ Signatures first": "✍️ Primero las firmas",
  "Do you already have the fully-signed contract in hand": "¿Ya tiene el contrato totalmente firmado en mano",
  "(signed outside the app)? If not: the offer stays pending — the offer's documents are in the deal's": "(firmado fuera de la aplicación)? Si no: la oferta queda pendiente — los documentos de la oferta están en la pestaña",
  "tab, where you can 📤 share them with the sellers or ✍️ send them for e-signature, then approve once everyone has signed.": "de la transacción, donde puede 📤 compartirlos con los vendedores o ✍️ enviarlos para firma electrónica, y luego aprobar una vez que todos hayan firmado.",
  "No — wait for signatures": "No — esperar las firmas",
  "Yes — it's fully signed, approve": "Sí — está totalmente firmado, aprobar",
  "📋 Review Extracted Contract Data": "📋 Revisar los datos extraídos del contrato",
  "Verify everything below is correct. Edit any field that's wrong. Click": "Verifique que todo lo siguiente sea correcto. Edite cualquier campo incorrecto. Haga clic en",
  "Approve Offer": "Aprobar oferta",
  "when ready — this accepts the offer, moves the listing to Under Contract, adds the parties, and sets up the timeline and tasks.": "cuando esté listo — esto acepta la oferta, mueve el listado a Bajo Contrato, agrega las partes y configura la cronología y las tareas.",
  "📄 Read the actual documents first": "📄 Primero lea los documentos originales",
  "Each opens in a new tab. The summary below is only what the AI read — the documents are the source of truth.": "Cada uno se abre en una nueva pestaña. El resumen a continuación es solo lo que la IA leyó — los documentos son la fuente de la verdad.",
  "Agent responsibility:": "Responsabilidad del agente:",
  "As the agent, you are legally responsible for verifying all extracted data is accurate before approval.": "Como agente, usted es legalmente responsable de verificar que todos los datos extraídos sean correctos antes de aprobar.",
  "AI Notes:": "Notas de la IA:",
  "ADDITIONAL TERMS / SPECIAL CLAUSES DETECTED": "TÉRMINOS ADICIONALES / CLÁUSULAS ESPECIALES DETECTADAS",
  "Additional Terms / Special Clauses": "Términos adicionales / Cláusulas especiales",
  "⚠️ Important:": "⚠️ Importante:",
  "These are CUSTOM clauses negotiated between parties (not standard form terms). They override standard contract terms.": "Estas son cláusulas PERSONALIZADAS negociadas entre las partes (no términos estándar del formulario). Tienen prioridad sobre los términos estándar del contrato.",
  "Read every line carefully": "Lea cada línea con atención",
  "— missing one can cost the buyer/seller money or break the deal. Edit below if the AI misread anything.": "— omitir una puede costarle dinero al comprador/vendedor o romper la transacción. Edite a continuación si la IA interpretó algo mal.",
  "ℹ️ On approval, this text will also be saved to the transaction Notes so you can find it later.": "ℹ️ Al aprobar, este texto también se guardará en las Notas de la transacción para que pueda encontrarlo después.",
  "✓ No additional terms or special clauses in this contract — nothing to review here. Leave it blank. (Only type something if the contract has an \"Additional Terms\" section the AI missed.)": "✓ No hay términos adicionales ni cláusulas especiales en este contrato — no hay nada que revisar aquí. Déjelo en blanco. (Escriba algo solo si el contrato tiene una sección de \"Términos adicionales\" que la IA haya omitido.)",
  "(blank — no additional terms)": "(en blanco — sin términos adicionales)",
  "📄 Documents Detected (": "📄 Documentos detectados (",
