  "— not found on the offer, please enter": "— no se encontró en la oferta, por favor ingrese",
  "Buy-side only. The listing-side commission already on the transaction is not changed. Used for pipeline & commission reporting.": "Solo del lado de la compra. La comisión del lado del listado ya registrada en la transacción no se modifica. Se usa para el informe de flujo y comisiones.",
  "👥 Parties (": "👥 Personas de la transacción (",
  "🏛️ Add your closing agent": "🏛️ Agregar su agente de cierre",
  "In Florida the closing is handled by a title company or a real estate attorney. Add them here so they're included in the transaction and receive the welcome email. (You can fill in their name and email below after adding.)": "En Florida, el cierre lo maneja una compañía de títulos o un abogado de bienes raíces. Agréguelo aquí para que se incluya en la transacción y reciba el correo de bienvenida. (Puede completar su nombre y correo electrónico después de agregarlo.)",
  "Your saved vendors": "Sus proveedores guardados",
  "+ Add New Title Company": "+ Agregar nueva compañía de títulos",
  "+ Add New Closing Attorney": "+ Agregar nuevo abogado de cierre",
