  "COMPANY": "COMPAÑÍA",
  "PHONE": "TELÉFONO",
  "LICENSE #": "N.° DE LICENCIA",
  "This offer is held in Pending Offers.": "Esta oferta se encuentra en Ofertas Pendientes.",
  "Save it now and come back later — share it with the sellers, hold several offers side by side, and only": "Guárdela ahora y vuelva más tarde — compártala con los vendedores, mantenga varias ofertas en paralelo, y solo",
  "Approve": "Apruebe",
  "once the sellers have signed/accepted. Approving accepts it into the transaction (Under Contract, parties, timeline & tasks).": "una vez que los vendedores hayan firmado/aceptado. Aprobar la acepta en la transacción (Bajo Contrato, partes, cronología y tareas).",
  "← Save to Pending Offers": "← Guardar en Ofertas Pendientes",
