  "We couldn't process this contract. Try again with a different file or use manual entry.": "No pudimos procesar este contrato. Intente de nuevo con otro archivo o use la entrada manual.",
  "Try Another File": "Probar con otro archivo",
  "Back": "Atrás",
  "Welcome! Let's get you set up.": "¡Bienvenido(a)! Vamos a configurar su cuenta.",
  "A few quick steps and you're ready to go — each one takes just a few minutes. We'll walk you through exactly where to click.": "Unos pasos rápidos y estará listo — cada uno toma solo unos minutos. Le mostraremos exactamente dónde hacer clic.",
  "Start setup →": "Iniciar configuración →",
  "▶ Watch the 2-minute tour": "▶ Ver el recorrido de 2 minutos",
