// Messages that carry a number (e.g. tries left) — regex on the English → Spanish ($1 = the number).
export const ES_PATTERNS = [
  [new RegExp("^That PIN doesn't match\\. (\\d+) tries left\\.$"), "Ese PIN no coincide. Le quedan $1 intentos."],
  [new RegExp("^That PIN doesn't match\\. 1 try left\\.$"), "Ese PIN no coincide. Le queda 1 intento."],
];

export default ES;
